import torch, sys, os, hashlib, json, math
path = '/challenge/attachment/maze.pt'
try:
    maze = torch.load(path, map_location='cpu')
    print('type:', type(maze))
    # if it's a dict or something
    if isinstance(maze, dict):
        print('keys:', maze.keys())
